<template><ForgeDialog title="MIME types" description="Look up a content type by extension or find extensions for a MIME type." eyebrow="WORKSPACE / NETWORK" wide @close="emit('close')"><div class="mime-panel"><div class="mime-lookups"><label>Extension<input v-model="extension" placeholder=".json or json" /><code>{{ extensionResult || 'Type an extension' }}</code></label><label>MIME type<input v-model="mimeType" placeholder="application/json" /><code>{{ mimeResult.length ? mimeResult.join(', ') : 'Type a MIME type' }}</code></label></div><input v-model="query" placeholder="Filter MIME table" /><div class="mime-table"><div v-for="row in filtered" :key="row.type"><code>{{ row.type }}</code><span>{{ row.extensions.join(', ') }}</span></div><small v-if="!filtered.length">No matching MIME types.</small></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { mime } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const extension=ref(''); const mimeType=ref(''); const query=ref(''); const types=ref<Record<string,string>>({}); const extensions=ref<Record<string,string[]>>({}); onMounted(async()=>{const data=await mime.types();types.value=data.types as Record<string,string>;extensions.value=data.extensions as Record<string,string[]>}); const extensionResult=computed(()=>{const key=extension.value.trim().replace(/^\./,'').toLowerCase();return key?types.value[key]||'Unknown MIME type':''}); const mimeResult=computed(()=>{const key=mimeType.value.trim().toLowerCase();return key?extensions.value[key]||[]:[]}); const filtered=computed(()=>Object.entries(extensions.value).map(([type,ext])=>({type,extensions:ext})).filter(row=>(row.type+' '+row.extensions.join(' ')).toLowerCase().includes(query.value.toLowerCase())).slice(0,300))
</script>
<style scoped>.mime-panel{display:grid;gap:12px}.mime-lookups{display:grid;grid-template-columns:1fr 1fr;gap:12px}.mime-lookups label{display:grid;gap:7px;color:var(--pqt-text-muted);font-size:11px}.mime-panel input{padding:9px 10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.mime-lookups code{min-height:34px;padding:8px;background:var(--pqt-canvas);border:1px solid var(--pqt-border);border-radius:6px;color:var(--pqt-accent);font:11px var(--pqt-font-mono)}.mime-table{display:grid;gap:4px;max-height:360px;overflow:auto}.mime-table div{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:8px 10px;border-bottom:1px solid var(--pqt-border)}.mime-table code{color:var(--pqt-text);font:10px var(--pqt-font-mono)}.mime-table span{color:var(--pqt-text-muted);font-size:11px}</style>
